ALTER TABLE "SessionLog" ADD COLUMN "externalRequestId" VARCHAR(200);
CREATE UNIQUE INDEX "SessionLog_externalRequestId_key" ON "SessionLog"("externalRequestId");
CREATE TABLE "WhatsAppLink" ("userId" UUID PRIMARY KEY REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE, "phone" VARCHAR(16) NOT NULL UNIQUE, "linkedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "WhatsAppReceipt" ("userId" UUID, "id" VARCHAR(200) PRIMARY KEY, "reply" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
